"""On-disk record format for the hash-chained audit log.

The format is unchanged from the single-file log: one compact JSON object
per line, sorted keys, raw non-ASCII, terminated by a single ``"\\n"``.
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

_RECORD_KEYS = {"digest", "payload", "prev", "tenant"}
_ENCODING = "utf-8"


def canonical_payload(payload: Any) -> str:
    """Compact JSON text used in the digest: sorted keys, raw non-ASCII."""
    return json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def digest(prev: str, payload: Any) -> str:
    material = prev + canonical_payload(payload)
    return hashlib.sha256(material.encode(_ENCODING)).hexdigest()


def canonical_json(value: Any) -> str:
    """Compact JSON text for manifest/cache bookkeeping."""
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def parse_line(line: str) -> dict:
    """Parse one on-disk line into a validated record or raise ValueError."""
    try:
        record = json.loads(line)
    except (json.JSONDecodeError, ValueError) as exc:
        raise ValueError("malformed audit record") from exc
    if not isinstance(record, dict) or set(record) != _RECORD_KEYS:
        raise ValueError("malformed audit record")
    if not isinstance(record["digest"], str):
        raise ValueError("malformed audit record: digest must be a string")
    if not isinstance(record["prev"], str):
        raise ValueError("malformed audit record: prev must be a string")
    if not isinstance(record["tenant"], str):
        raise ValueError("malformed audit record: tenant must be a string")
    if not isinstance(record["payload"], dict):
        raise ValueError("malformed audit record: payload must be an object")
    return record


def split_records(text: str) -> list[str]:
    """Split log text into lines the same way the single-file log did.

    Every complete record ends with a newline; bytes after the final newline
    are a half-written line left by a crashed append and are reported as a
    truncated record rather than silently dropped.
    """
    if text == "":
        return []
    if not text.endswith("\n"):
        raise ValueError("truncated audit record")
    # The trailing newline leaves one final empty segment, which is the only
    # empty segment a healthy log contains.
    return text.split("\n")[:-1]


def build_line(tenant: str, payload: Any, prev: str) -> tuple[dict, str]:
    """Build the stored record and its canonical on-disk line."""
    record = {
        "digest": digest(prev, payload),
        "payload": payload,
        "prev": prev,
        "tenant": tenant,
    }
    line = canonical_json(record)
    return record, line

def _collect_range(
    self, units: list[dict], tenant: str, start: int, end: int
) -> dict:
    """One ordered snapshot scan collecting interval material.

    Windows are numbered with one strictly increasing global sequence
    across all units, so the proof carries an explicit cross-segment
    window chain. Only records of ``tenant`` are parsed; malformed lines
    and a trailing half line outside the interval are skipped, so damage
    outside the interval cannot change its conclusion.
    """
    buckets: dict[int, list[tuple[int, int, dict]]] = {}
    anchors: dict[int, dict] = {}
    predecessor: Optional[str] = None
    count = 0
    global_seq = 0

    for unit in units:
        try:
            with open(unit["path"], "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if not unit["sealed"]:
                continue
            raise

        parts = unit["parts"]
        window_ends: list[int] = []
        running = 0
        for part in parts:
            running += part["size"]
            window_ends.append(running)
            anchors[global_seq + len(window_ends) - 1] = {
                "name": part["name"],
                "size": part["size"],
                "sha256": part["sha256"],
            }
        tail_offset = running
        tail_seq = global_seq + len(parts)
        if len(raw) > tail_offset:
            anchors[tail_seq] = {
                "name": unit["name"],
                "size": len(raw) - tail_offset,
                "sha256": _sha256(raw[tail_offset:]),
            }
        elif not parts:
            # Legacy/active unit with no preserved material: its whole
            # bytes are one implicit window.
            anchors[tail_seq] = {
                "name": unit["name"],
                "size": len(raw),
                "sha256": _sha256(raw),
            }

        # Whole-line scan: a piece after the final newline is a crashed
        # half line -- never a record, and irrelevant when out of range.
        pos = 0
        for line_raw in raw.split(b"\n")[:-1]:
            line_start = pos
            line_end = pos + len(line_raw) + 1
            pos = line_end
            try:
                record = st.decode_records(line_raw + b"\n")[0]
            except ValueError:
                continue
            if record["tenant"] != tenant:
                continue
            if count == start:
                predecessor = record["prev"]
            win_index = 0
            while win_index < len(window_ends) and line_start >= window_ends[win_index]:
                win_index += 1
            if win_index < len(window_ends):
                seq = global_seq + win_index
                window_start = window_ends[win_index - 1] if win_index else 0
            else:
                seq = tail_seq
                window_start = tail_offset
            if start <= count < end:
                buckets.setdefault(seq, []).append(
                    (count, line_start - window_start, record)
                )
            count += 1

        global_seq += len(parts) + (1 if len(raw) > tail_offset or not parts else 0)

    if count == 0:
        if (start, end) == (0, 0):
            return {
                "tenant": tenant,
                "start": 0,
                "end": 0,
                "count": 0,
                "prev": "",
                "anchors": {},
                "buckets": [],
            }
        raise ValueError("range is out of bounds for an empty history")
    if start == end:
        raise ValueError("range must be a non-empty interval")
    if start >= count or end > count:
        raise ValueError("range is out of bounds")

    return {
        "tenant": tenant,
        "start": start,
        "end": end,
        "count": count,
        "prev": predecessor if predecessor is not None else "",
        "anchors": anchors,
        "buckets": [
            {"seq": seq, "records": records}
            for seq, records in sorted(buckets.items())
        ],
    }

# ------------------------------------------------------------------
# Bounded-export fast path (warm, authenticated verify cache)
# ------------------------------------------------------------------

def _export_guide(
    self, units: list[dict], layout: st.Layout, tenant: str
) -> Optional[list[int]]:
    """Each unit's cumulative tenant record count, or None when cold.

    The verify cache is signed and a unit is adopted only when the exact
    stat guard and its preserved-window material both match, so a
    rewritten prefix, a same-size edit, a shrunk file, a grown active
    unit or an edited manifest window all force the full byte scan
    instead of trusting a guide that no longer matches the bytes.
    """
    try:
        cache = st.load_cache(layout)
    except st.AuditMetadataError:
        return None
    if cache is None or len(cache["segments"]) != len(units):
        return None

    counts: list[int] = []
    for unit in units:
        entry = cache["segments"].get(unit["name"])
        if entry is None:
            return None
        try:
            stat = os.stat(unit["path"])
        except FileNotFoundError:
            if not unit["sealed"]:
                return None
            raise
        if not self._entry_fresh(entry, stat, unit):
            return None
        state = entry["tenants"].get(tenant)
        counts.append(state[0] if state is not None else 0)
    return counts

def _collect_range_bounded(
    self,
    units: list[dict],
    tenant: str,
    start: int,
    end: int,
    counts: list[int],
) -> dict:
    """Collect interval material opening only covering units.

    Only the units that hold an interval record are read. A record in a
    preserved sealed window is anchored by that window's manifest
    material, so no sealed byte is hashed; records in the still-growing
    un-preserved tail of an active/legacy unit are grouped into small
    windows that contain only the interval's own consecutive lines, so
    digest work tracks the interval rather than the unit. Total cost
    therefore grows with the interval and the (bounded) covering units,
    never with overall history length: non-covering units are never
    opened and their sealed windows contribute no reads or hashes.
    """
    total = counts[-1]
    if total == 0:
        if (start, end) == (0, 0):
            return {
                "tenant": tenant,
                "start": 0,
                "end": 0,
                "count": 0,
                "prev": "",
                "anchors": {},
                "buckets": [],
            }
        raise ValueError("range is out of bounds for an empty history")
    if start == end:
        raise ValueError("range must be a non-empty interval")
    if start >= total or end > total:
        raise ValueError("range is out of bounds")

    # A one-shot export is the degenerate sharded collection: a
    # single window covering the whole interval.
    return next(
        iter(
            self._collect_shards_bounded(
                units, tenant, start, end, counts, end - start
            )
        )
    )

def _collect_shards_bounded(
    self,
    units: list[dict],
    tenant: str,
    start: int,
    end: int,
    counts: list[int],
    window: int,
) -> Iterator[dict]:
    """Yield shard materials for ``[start, end)`` in window-sized pieces.

    One ordered pass over the covering units: each unit is opened at
    most once and only the current shard's records are retained, so
    memory tracks a single window, never the interval or the
    history. Anchoring is exactly the bounded exporter's -- manifest
    windows for preserved sealed bytes, narrowed runs of consecutive
    interval lines in a growing tail -- so a shard boundary landing
    inside a preserved window carries the same anchor on both sides
    and :func:`audit_chain.proof.combine_proofs` merges the two
    halves back into one window.
    """
    total = counts[-1]
    first_unit = self._first_unit_for(counts, start)
    last_unit = self._first_unit_for(counts, end - 1)

    # Current shard's emitted windows in physical order; seqs are
    # assigned per shard at flush time so each shard's window chain
    # is strictly increasing from zero.
    shard_start = start
    shard_end = min(start + window, end)
    emitted: list[dict] = []
    sealed_index: dict[tuple[int, int], int] = {}
    predecessor: Optional[str] = None

    for ui in range(first_unit, last_unit + 1):
        unit = units[ui]
        with open(unit["path"], "rb") as handle:
            raw = handle.read()

        parts = unit["parts"]
        window_ends: list[int] = []
        running = 0
        for part in parts:
            running += part["size"]
            window_ends.append(running)

        # Pending narrowed tail window: [blob, slots]. It holds one
        # run of physically consecutive interval lines, so its bytes
        # contain only interval records -- no other-tenant or
        # out-of-range line.
        run: Optional[list] = None
        prev_tail_end: Optional[int] = None
        base = counts[ui - 1] if ui else 0
        local = base
        pos = 0

        def flush_tail() -> None:
            nonlocal run
            if not run:
                run = None
                return
            blob, slots = run
            emitted.append(
                {
                    "name": unit["name"],
                    "size": len(blob),
                    "sha256": _sha256(blob),
                    "records": slots,
                }
            )
            run = None

        for line_raw in raw.split(b"\n")[:-1]:
            line_start = pos
            line = line_raw + b"\n"
            pos += len(line)
            try:
                record = st.decode_records(line)[0]
            except ValueError:
                record = None
            is_tenant = record is not None and record["tenant"] == tenant
            included = is_tenant and shard_start <= local < shard_end

            if is_tenant and local == shard_start:
                predecessor = record["prev"]

            if included:
                win_index = 0
                while (
                    win_index < len(window_ends)
                    and line_start >= window_ends[win_index]
                ):
                    win_index += 1
                if win_index < len(window_ends):
                    # Preserved sealed window: reuse the manifest anchor.
                    flush_tail()
                    prev_tail_end = line_start + len(line)
                    window_start = window_ends[win_index - 1] if win_index else 0
                    key = (ui, win_index)
                    slot_pos = sealed_index.get(key)
                    if slot_pos is None:
                        part = parts[win_index]
                        slot_pos = len(emitted)
                        sealed_index[key] = slot_pos
                        emitted.append(
                            {
                                "name": part["name"],
                                "size": part["size"],
                                "sha256": part["sha256"],
                                "records": [],
                            }
                        )
                    emitted[slot_pos]["records"].append(
                        (local, line_start - window_start, record)
                    )
                else:
                    # Growing tail: consecutive interval lines share one
                    # small window; any intervening physical line (another
                    # tenant, an out-of-range record, a bad line) splits it.
                    if run is None or line_start != prev_tail_end:
                        flush_tail()
                        run = [b"", []]
                    offset_in_run = len(run[0])
                    run[0] += line
                    run[1].append((local, offset_in_run, record))
                    prev_tail_end = line_start + len(line)
            else:
                flush_tail()
                prev_tail_end = None

            if is_tenant:
                local += 1
                if local == shard_end:
                    # The shard is complete: seal it before any later
                    # record (or unit) is touched, so only one
                    # window's material is ever retained.
                    flush_tail()
                    anchors = {
                        seq: {
                            "name": item["name"],
                            "size": item["size"],
                            "sha256": item["sha256"],
                        }
                        for seq, item in enumerate(emitted)
                    }
                    material = {
                        "tenant": tenant,
                        "start": shard_start,
                        "end": shard_end,
                        "count": total,
                        "prev": predecessor if predecessor is not None else "",
                        "anchors": anchors,
                        "buckets": [
                            {"seq": seq, "records": item["records"]}
                            for seq, item in enumerate(emitted)
                        ],
                    }
                    shard_start = shard_end
                    shard_end = min(shard_end + window, end)
                    emitted = []
                    sealed_index = {}
                    predecessor = None
                    yield material

        flush_tail()

@staticmethod
def _first_unit_for(counts: list[int], index: int) -> int:
    """First unit whose cumulative tenant count is greater than ``index``."""
    for ui, cumulative in enumerate(counts):
        if cumulative > index:
            return ui
    return len(counts) - 1

